import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 촉진 단계는 1차·2차만 허용한다 (법령 및 사내 기준은 확인 필요).
const PROMOTION_STAGES = ['1차', '2차'];
// 가정: 목록 크기 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function toId(value: unknown): string {
  const text = String(value ?? '').trim();
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '숫자 ID 형식이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr01906Controller {
  @Post('/leave-promotions')
  @HttpCode(200)
  async createLeavePromotion(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const annualLeaveId = toId(data['annualLeaveId']);
    const employeeId = toId(data['employeeId']);
    const promotionStage = String(data['promotionStage'] ?? '').trim();
    const noticeDate = String(data['noticeDate'] ?? '').trim();
    if (promotionStage === '' || noticeDate === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '촉진 단계와 통보일은 필수입니다.');
    }
    if (!PROMOTION_STAGES.includes(promotionStage)) {
      throw new ApiError(422, 'INVALID_PROMOTION_STAGE', '촉진 단계가 기준에 맞지 않습니다.');
    }
    if (!DATE_PATTERN.test(noticeDate)) {
      throw new ApiError(422, 'INVALID_PROMOTION_STAGE', '통보일 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const leaves = await db.query(
        'SELECT annual_leave_id FROM annual_leave WHERE annual_leave_id = CAST(:annualLeaveId AS bigint) AND employee_id = CAST(:employeeId AS bigint)',
        { annualLeaveId, employeeId },
      );
      if (leaves.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '대상 임직원의 연차가 생성되어 있지 않습니다.');
      }
      const dup = await db.query(
        'SELECT leave_promotion_id FROM leave_promotion WHERE annual_leave_id = CAST(:annualLeaveId AS bigint) AND promotion_stage = :promotionStage',
        { annualLeaveId, promotionStage },
      );
      if (dup.length > 0) {
        throw new ApiError(422, 'INVALID_PROMOTION_STAGE', '이미 등록된 촉진 단계입니다.');
      }
      const rows = await db.query(
        'INSERT INTO leave_promotion (annual_leave_id, employee_id, promotion_stage, notice_date, created_at, updated_at) '
          + 'VALUES (CAST(:annualLeaveId AS bigint), CAST(:employeeId AS bigint), :promotionStage, CAST(:noticeDate AS date), now(), now()) '
          + 'RETURNING leave_promotion_id AS "leavePromotionId"',
        { annualLeaveId, employeeId, promotionStage, noticeDate },
      );
      return rows[0];
    });
  }

  @Get('/leave-promotions')
  async listLeavePromotions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const pageText = String(query['page'] ?? '').trim();
    const sizeText = String(query['size'] ?? '').trim();
    const page = pageText === '' ? 0 : Number(pageText);
    let size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const fromDate = String(query['fromDate'] ?? '').trim();
    const toDate = String(query['toDate'] ?? '').trim();
    const departmentText = String(query['departmentId'] ?? '').trim();
    if (fromDate !== '' && !DATE_PATTERN.test(fromDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일 형식이 올바르지 않습니다.');
    }
    if (toDate !== '' && !DATE_PATTERN.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const params: Record<string, unknown> = {};
      let where = ' WHERE 1 = 1';
      if (fromDate !== '') {
        where += ' AND lp.notice_date >= CAST(:fromDate AS date)';
        params['fromDate'] = fromDate;
      }
      if (toDate !== '') {
        where += ' AND lp.notice_date <= CAST(:toDate AS date)';
        params['toDate'] = toDate;
      }
      if (departmentText !== '') {
        where += ' AND e.department_id = CAST(:departmentId AS bigint)';
        params['departmentId'] = toId(departmentText);
      }
      const from = ' FROM leave_promotion lp JOIN employee e ON e.employee_id = lp.employee_id JOIN annual_leave al ON al.annual_leave_id = lp.annual_leave_id ';
      const counted = await db.query('SELECT COUNT(*) AS total' + from + where, params);
      const total = Number(counted[0]?.total ?? 0);
      const items = await db.query(
        'SELECT lp.leave_promotion_id AS "leavePromotionId", lp.employee_id AS "employeeId", lp.promotion_stage AS "promotionStage", '
          + 'lp.notice_date AS "noticeDate", al.used_days AS "usedDays"'
          + from
          + where
          + ' ORDER BY lp.notice_date DESC, lp.leave_promotion_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }
}

