import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSfr01906Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<'' | 'promotion' | 'plan'>('');

  const [annualLeaveId, setAnnualLeaveId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [promotionStage, setPromotionStage] = useState('');
  const [noticeDate, setNoticeDate] = useState('');

  const [planEmployeeId, setPlanEmployeeId] = useState<number | string>('');
  const [planMonth, setPlanMonth] = useState('');
  const [planDate, setPlanDate] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/leave-promotions', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page],
  );

  function search() {
    setPage(0);
    setApplied({ fromDate, toDate, departmentId });
  }

  function reset() {
    setFromDate('');
    setToDate('');
    setDepartmentId('');
    setPage(0);
    setApplied({});
  }

  async function submitPromotion() {
    if (annualLeaveId === '' || employeeId === '' || promotionStage === '' || noticeDate === '') {
      throw new Error('연차, 촉진 대상 임직원, 촉진 단계, 통보일을 모두 입력하세요.');
    }
    await call('POST', '/leave-promotions', role, { annualLeaveId, employeeId, promotionStage, noticeDate });
    notify('연차사용촉진계획을 등록했습니다.');
    setDrawer('');
    setAnnualLeaveId('');
    setEmployeeId('');
    setPromotionStage('');
    setNoticeDate('');
    reload();
  }

  async function submitPlan() {
    if (planEmployeeId === '' || planMonth === '' || planDate === '') {
      throw new Error('임직원, 계획 연월, 계획 일자를 모두 입력하세요.');
    }
    await call('POST', '/annual-leave-plans', role, {
      employeeId: planEmployeeId,
      planMonth,
      planDate,
    });
    notify('월별 연차계획을 등록했습니다.');
    setDrawer('');
    setPlanEmployeeId('');
    setPlanMonth('');
    setPlanDate('');
  }

  const rows = data?.items ?? [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>촉진 현황</h2>
        <Tiles items={[['조회 건수', <Num value={data?.total ?? 0} />]]} />
      </section>
      <section className="box span-12">
        <h2>연차사용촉진</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="부서 조건">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type="button" onClick={() => setDrawer('plan')}>연차계획 등록</button>
          <button type="button" onClick={() => setDrawer('promotion')}>촉진계획 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          empty="조회된 촉진 내역이 없습니다."
          columns={[
            { key: 'leavePromotionId', label: '연차사용촉진 ID' },
            {
              key: 'employeeId',
              label: '촉진 대상 임직원',
              render: (r) => <RefName table="employee" role={role} value={r.employeeId} />,
            },
            { key: 'promotionStage', label: '촉진 단계', render: (r) => <Badge value={r.promotionStage} /> },
            { key: 'noticeDate', label: '통보일', render: (r) => <DateText value={r.noticeDate} /> },
            { key: 'usedDays', label: '사용 일수', render: (r) => <Num value={r.usedDays} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {drawer === 'promotion' ? (
        <Drawer title="연차사용촉진계획 등록" onClose={() => setDrawer('')}>
          <Form onSubmit={submitPromotion} submit="등록">
            <Field label="연차" required>
              <LookupSelect table="annual_leave" role={role} value={annualLeaveId} onChange={setAnnualLeaveId} />
            </Field>
            <Field label="촉진 대상 임직원" required>
              <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
            <Field label="촉진 단계" required>
              <Select
                value={promotionStage}
                onChange={setPromotionStage}
                options={[['1차', '1차'], ['2차', '2차']]}
              />
            </Field>
            <Field label="통보일" required>
              <DateInput value={noticeDate} onChange={setNoticeDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {drawer === 'plan' ? (
        <Drawer title="월별 연차계획 등록" onClose={() => setDrawer('')}>
          <Form onSubmit={submitPlan} submit="등록">
            <Field label="임직원" required>
              <LookupSelect table="employee" role={role} value={planEmployeeId} onChange={setPlanEmployeeId} />
            </Field>
            <Field label="계획 연월" required hint="YYYY-MM">
              <TextInput value={planMonth} onChange={setPlanMonth} placeholder="2025-01" />
            </Field>
            <Field label="계획 일자" required>
              <DateInput value={planDate} onChange={setPlanDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
